'use strict';
/* Bundles the knowledge + engine modules into one browser file.
 * Run: node build/bundle.js
 *
 * Deliberately a tiny CommonJS shim rather than a transform: the source files
 * ship to the browser byte-for-byte identical to the ones under test. A second
 * hand-maintained copy of this logic would drift, and the drift would be
 * invisible until it gave a customer a wrong number. */

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const MODULES = [
  'knowledge/benchmarks',
  'knowledge/doctrine',
  'knowledge/practice',
  'knowledge/catalog',
  'engine/digest',
  'engine/recommend',
  'engine/planner',
  'engine/lead',
];

const SHIM_HEAD = `/* GENERATED by build/bundle.js — do not edit. Edit the source modules. */
(function (global) {
  'use strict';
  var registry = {}, cache = {};
  function def(id, fn) { registry[id] = fn; }
  function norm(from, spec) {
    if (spec.charAt(0) !== '.') return spec;
    var parts = from.split('/').slice(0, -1).concat(spec.split('/'));
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      var p = parts[i];
      if (p === '.' || p === '') continue;
      if (p === '..') out.pop(); else out.push(p);
    }
    return out.join('/');
  }
  function req(from, spec) {
    var id = norm(from, spec);
    if (cache[id]) return cache[id].exports;
    if (!registry[id]) throw new Error('module not bundled: ' + id);
    var m = { exports: {} };
    cache[id] = m;
    registry[id](m, m.exports, function (s) { return req(id, s); });
    return m.exports;
  }
`;

const SHIM_TAIL = `
  global.PMEngine = {
    digest: req('', './engine/digest'),
    recommend: req('', './engine/recommend'),
    planner: req('', './engine/planner'),
    lead: req('', './engine/lead'),
    knowledge: {
      benchmarks: req('', './knowledge/benchmarks'),
      doctrine: req('', './knowledge/doctrine'),
      practice: req('', './knowledge/practice'),
      catalog: req('', './knowledge/catalog')
    }
  };
})(typeof window !== 'undefined' ? window : this);
`;

let out = SHIM_HEAD;
for (const id of MODULES) {
  const src = fs.readFileSync(path.join(root, `${id}.js`), 'utf8');
  out += `\n  def(${JSON.stringify(id)}, function (module, exports, require) {\n${src}\n  });\n`;
}
out += SHIM_TAIL;

const dest = path.join(root, 'site', 'engine.bundle.js');
fs.mkdirSync(path.dirname(dest), { recursive: true });
fs.writeFileSync(dest, out);

console.log(`wrote site/engine.bundle.js (${(out.length / 1024).toFixed(1)} KB, ${MODULES.length} modules)`);
